function [xft,xftu,xftl] = ft_llm_dke_yp(xia,ntheta)%%Fraction of trapped electrons as calculated by Y.R. Lin-Liu and R.L. Miller in Phys. Plasma 2 (1995) 1666%Elliptic plasma equilbrium case only%%	Input:%%		- xia: inverse aspect ratio [1,m]%		- ntheta: number of poloidal angle values [1,1]%%	Output:%%		- ftu: Upper boundary value of the trapped electron fraction [1,m]%		- ftl: Upper boundary value of the trapped electron fraction [1,m]%		- ft: Interpolated value of the trapped electron fraction [1,m]%%by Y.PEYSSON CEA-DRFC 12/12/2002 <yves.peysson@cea.fr>%if nargin < 1,	infoyp(2,'Wrong number of input arguments for ft_llm_dke_yp');	return;end%if nargin == 1,	ntheta = 100;end%xh = 1 - xia;xh2 = ((1 - xia).^(1.5))./sqrt(1 + xia);%theta = linspace(0,2*pi,ntheta)'*ones(size(xia));dtheta = (theta(3)-theta(2)).*ones(size(theta(:,1)));%xpsi = (1 + ones(ntheta,1)*xia)./(1 + cos(theta).*(ones(ntheta,1)*xia));xrr = (1 - ones(ntheta,1)*xia)./(1 + ones(ntheta,1)*xia);xf = (1 - sqrt(1 - xrr.*xpsi).*(1 + 0.5*xrr.*xpsi))./xpsi.^3;xftl1 = (((1+xia).^3)./(1-xia).^2).*integral_dke_jd(dtheta(:,1),xf,1)'/2/pi;%xftu = 1 - (xh2./xh./xh).*(1 - sqrt(1 - xh).*(1 + 0.5*xh));xftl = 1 - xh2.*xftl1;xft = 0.75*xftu+0.25*xftl;